import { Launchpage } from "english-olabsnxtg-library";
import ActStartPopupContent from "./ActStartPopupContent";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";

const HomePage = () => {
  const { t, i18n } = useTranslation();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  let arr = [t("learning_out_title1")];
  return (
    <Launchpage
      L_title={t("title")}
      L_objective={t("objective")}
      L_act_objective={t("objectivedef")}
      L_learning_outcome={t("learning_out_title")}
      L_array={arr}
      L_startbutton={t("start")}
      WAWGTL_comp={<ActStartPopupContent />}
      WAWGTL_title_string={t("what_we_are_going_to_learn_title")}
      ok={t("ok")}
      cancel={t("cancel")}
      WS_sendJsonMessage={sendJsonMessage}
      WS_SendLogData={SendLogData}
      labNo="CDAC-OlabsNxtG-Hi-21"
      labShortName="Transitive and Intransitive Verb"
    />
  );
};

export default HomePage;
