import { useEffect, useState } from "react";
import { Button } from "@mui/material";
import { useNavigate } from "react-router-dom";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import video from "../Images/intro_video.mp4";
import { useTranslation } from "react-i18next";

const Selectlevel = () => {
  const { t, i18n } = useTranslation();
  // Load Json to mainArr variable ....
  const navigate = useNavigate();

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level start page");

  var [flag, setFlag] = useState(true);

  useEffect(() => {
    if (flag) {
      document
        .getElementById("myVideo")
        .addEventListener("loadedmetadata", function () {
          document.getElementById("myVideo").play();
        });
    }
  }, [flag]);

  const tolevel1 = () => {
    ReactGA.event({
      action:
        "English Transitive and Intransitive Verb | CDAC-OlabsNxtG-En-21 | Clicked on Let's Go button",
      category: "English CDAC-OlabsNxtG-En-21 | Let's Go button clicked",
      label:
        "English CDAC-OlabsNxtG-En-21 | Let's Go button clicked and go to level-1 of a game.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Let's Go button",
      "Clicked",
      "Let's Go button clicked and go to level-1 of a game."
    );

    navigate("/launchpage/englishactivity/level1");
  };

  const skipbtn = () => {
    ReactGA.event({
      action:
        "English Transitive and Intransitive Verb | CDAC-OlabsNxtG-En-21 | Clicked on 'Skip' button",
      category: "English CDAC-OlabsNxtG-En-21 | Skip button clicked",
      label:
        "English CDAC-OlabsNxtG-En-21 | Skip button clicked and introduction video skipped.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Skip button",
      "Clicked",
      "Skip button clicked and introduction video skipped."
    );

    navigate("/launchpage/englishactivity/level1");
  };

  const end = () => {
    setFlag(false);
  };

  return (
    <div
      className="row scrollbar-primary d-flex "
      style={{
        height: "100%",
        width: "100%",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        marginLeft: "auto",
        marginRight: "auto",
        overflow: "auto",
      }}
    >
      <div
        className="row d-flex justify-content-center align-items-center"
        style={{ height: "90%" }}
      >
        {flag == true ? (
          <video
            className="video"
            id="myVideo"
            width="50%"
            height="65%"
            //  width="50%"
            // height="50%"
            autoplay
            muted
            onEnded={end}
          >
            <source src={video} type="video/mp4" />
          </video>
        ) : (
          <div className="d-flex justify-content-center">
            <h6
              style={{
                background: "#EDF6FA",
                boxShadow: "rgba(0, 0, 0, 0.25) 0px 54px 55px, rgba(0, 0, 0, 0.12) 0px -12px 30px, rgba(0, 0, 0, 0.12) 0px 4px 6px, rgba(0, 0, 0, 0.17) 0px 12px 13px, rgba(0, 0, 0, 0.09) 0px -3px 5px",
                padding: "2vh",
                borderRadius: "1vh",
              }}
            >
              Click on "LET'S GO" button to start the activity.
            </h6>
          </div>
        )}
      </div>
      <div
        className=" d-flex justify-content-center align-items-center justify-content-around"
        style={{ height: "10%" }}
      >
        <Button
          id="skip"
          variant="contained"
          onClick={skipbtn}
          disabled={flag == false}
          sx={{ fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E" }}
        >
          {t("skip")}
        </Button>

        <Button
          id="letgo"
          variant="contained"
          onClick={tolevel1}
          disabled={flag}
          sx={{ fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E" }}
        >
          {t("lets_go")}
        </Button>
      </div>

      {/* <InfoPopUpForDetailView
      openDialog={showDialogue}
      onAgree={onAgree}
      content={<ViewDetailsPopup sentence={sentence} />}
      popuptitle="Hint"
    /> */}
    </div>
  );
};

export default Selectlevel;
